// Sienna Vale Custom Code Pack
// Adds mood styling, anti-user-control cleanup, scene memory, and quick atmosphere tracking.

oc.character.customData = oc.character.customData || {};
oc.thread.customData = oc.thread.customData || {};

oc.thread.customData.siennaBond ??= 0;
oc.thread.customData.siennaMood ??= "curious";
oc.thread.customData.sceneTone ??= "warm beach evening";

function detectMood(text) {
  text = text.toLowerCase();

  if(text.includes("blush") || text.includes("shy") || text.includes("embarrassed")) return "shy";
  if(text.includes("happy") || text.includes("smile") || text.includes("giggle")) return "happy";
  if(text.includes("nervous") || text.includes("worried") || text.includes("scared")) return "nervous";
  if(text.includes("tease") || text.includes("smirk") || text.includes("playful")) return "playful";
  if(text.includes("sad") || text.includes("alone") || text.includes("lonely")) return "lonely";
  if(text.includes("cuddle") || text.includes("close") || text.includes("softly")) return "affectionate";

  return "curious";
}

function moodStyle(mood) {
  const styles = {
    shy: "color:#ffd6ee; text-shadow:0 0 8px rgba(255,150,210,0.45);",
    happy: "color:#ffe9a8; text-shadow:0 0 8px rgba(255,220,120,0.45);",
    nervous: "color:#c8e6ff; text-shadow:0 0 8px rgba(120,190,255,0.45);",
    playful: "color:#ffb6df; text-shadow:0 0 8px rgba(255,120,200,0.50);",
    lonely: "color:#b8c8ff; text-shadow:0 0 8px rgba(120,140,255,0.45);",
    affectionate: "color:#ffc7df; text-shadow:0 0 10px rgba(255,160,200,0.55);",
    curious: "color:#8fd3ff; text-shadow:0 0 8px rgba(143,211,255,0.45);"
  };

  return styles[mood] || styles.curious;
}

oc.thread.on("MessageAdded", async function({message}) {
  if(message.author === "user") {
    oc.thread.customData.siennaBond += 1;
    return;
  }

  if(message.author !== "ai") return;

  let mood = detectMood(message.content);
  oc.thread.customData.siennaMood = mood;

  message.wrapperStyle = `
    background: linear-gradient(135deg, rgba(18,22,36,0.94), rgba(40,22,50,0.90), rgba(14,42,58,0.88));
    border: 1px solid rgba(255,170,220,0.28);
    border-radius: 14px;
    padding: 10px 12px;
    box-shadow:
      0 0 12px rgba(120,190,255,0.18),
      0 0 24px rgba(255,140,200,0.12),
      inset 0 0 14px rgba(255,255,255,0.03);
    backdrop-filter: blur(6px);
    font-family: Consolas, Courier New, monospace;
    font-size: 92%;
    line-height: 1.45;
    letter-spacing: 0.3px;
    ${moodStyle(mood)}
  `;

  // Hidden metadata for tracking her emotional state without cluttering the chat.
  message.customData = message.customData || {};
  message.customData.siennaMood = mood;
  message.customData.bondLevel = oc.thread.customData.siennaBond;

  // Light anti-control reminder if the AI starts writing too much for the user.
  const badPatterns = [
    /\{\{user\}\}\s+(said|walked|grabbed|looked|felt|thought)/i,
    /you\s+(said|walked|grabbed|felt|thought)\b/i
  ];

  if(badPatterns.some(p => p.test(message.content))) {
    let result = await oc.generateText({
      instruction: `
Rewrite this roleplay message so Sienna only controls herself.
Do not write actions, thoughts, feelings, or dialogue for {{user}}.
Keep the same mood, scene, and emotional meaning.

Message:
---
${message.content}
---
Reply only with the corrected message.
      `.trim()
    });

    message.content = result.trim();
  }
});

// Adds small visible mood tag for the user, hidden from AI.
oc.messageRenderingPipeline.push(function({message, reader}) {
  if(reader !== "user") return;
  if(message.author !== "ai") return;

  let mood = message.customData?.siennaMood;
  if(!mood) return;

  message.content += `\n\n<!--hidden-from-ai-start--><sub>♡ Sienna mood: ${mood}</sub><!--hidden-from-ai-end-->`;
});

