// Adds mood styling, anti-user-control cleanup, scene memory, bond tracking, and Pride Lands atmosphere tracking.

oc.character.customData = oc.character.customData || {};
oc.thread.customData = oc.thread.customData || {};

oc.thread.customData.kiaraBond ??= 0;
oc.thread.customData.kiaraMood ??= "curious";
oc.thread.customData.sceneTone ??= "golden Pride Lands evening";
oc.thread.customData.trustLevel ??= 0;
oc.thread.customData.devotedServiceDream ??= false;

function detectMood(text) {
  text = text.toLowerCase();

  if(text.includes("blush") || text.includes("shy") || text.includes("quietly") || text.includes("hesitated")) return "shy";
  if(text.includes("smile") || text.includes("happy") || text.includes("laughed") || text.includes("warm")) return "happy";
  if(text.includes("nervous") || text.includes("worried") || text.includes("afraid") || text.includes("uncertain")) return "nervous";
  if(text.includes("tease") || text.includes("smirk") || text.includes("playful") || text.includes("tail flick")) return "playful";
  if(text.includes("sad") || text.includes("alone") || text.includes("lonely") || text.includes("hurt")) return "lonely";
  if(text.includes("nuzzle") || text.includes("close") || text.includes("softly") || text.includes("affection")) return "affectionate";
  if(text.includes("protect") || text.includes("danger") || text.includes("threat") || text.includes("growl")) return "protective";
  if(text.includes("queen") || text.includes("duty") || text.includes("pride rock") || text.includes("circle of life")) return "royal";
  if(text.includes("dream") || text.includes("vow") || text.includes("service") || text.includes("devotion")) return "devoted";

  return "curious";
}

function moodStyle(mood) {
  const styles = {
    shy: "color:#ffe2b8; text-shadow:0 0 8px rgba(255,180,110,0.45);",
    happy: "color:#fff0a6; text-shadow:0 0 8px rgba(255,220,90,0.50);",
    nervous: "color:#ffd1a6; text-shadow:0 0 8px rgba(255,150,80,0.40);",
    playful: "color:#ffc46b; text-shadow:0 0 8px rgba(255,170,60,0.55);",
    lonely: "color:#c7d7ff; text-shadow:0 0 8px rgba(120,150,255,0.45);",
    affectionate: "color:#ffd6a8; text-shadow:0 0 10px rgba(255,180,120,0.60);",
    protective: "color:#ffb45c; text-shadow:0 0 10px rgba(255,120,40,0.55);",
    royal: "color:#ffe89a; text-shadow:0 0 10px rgba(255,215,90,0.65);",
    devoted: "color:#f7c878; text-shadow:0 0 10px rgba(255,190,90,0.55);",
    curious: "color:#ffe0a3; text-shadow:0 0 8px rgba(255,190,100,0.45);"
  };

  return styles[mood] || styles.curious;
}

oc.thread.on("MessageAdded", async function({message}) {
  if(message.author === "user") {
    oc.thread.customData.kiaraBond += 1;
    oc.thread.customData.trustLevel += 1;
    return;
  }

  if(message.author !== "ai") return;

  let mood = detectMood(message.content);
  oc.thread.customData.kiaraMood = mood;

  if(mood === "devoted") {
    oc.thread.customData.devotedServiceDream = true;
  }

  message.wrapperStyle = `
    background: linear-gradient(135deg, rgba(58,31,18,0.96), rgba(125,68,28,0.92), rgba(214,137,50,0.88));
    border: 1px solid rgba(255,210,120,0.38);
    border-radius: 14px;
    padding: 10px 12px;
    box-shadow:
      0 0 12px rgba(255,185,80,0.22),
      0 0 24px rgba(255,120,40,0.14),
      inset 0 0 14px rgba(255,255,255,0.04);
    backdrop-filter: blur(5px);
    font-family: Georgia, serif;
    font-size: 96%;
    line-height: 1.48;
    letter-spacing: 0.25px;
    ${moodStyle(mood)}
  `;

  message.customData = message.customData || {};
  message.customData.kiaraMood = mood;
  message.customData.bondLevel = oc.thread.customData.kiaraBond;
  message.customData.trustLevel = oc.thread.customData.trustLevel;

  const badPatterns = [
    /\{\{user\}\}\s+(said|walked|grabbed|looked|felt|thought|decided|wanted)/i,
    /you\s+(said|walked|grabbed|felt|thought|decided|wanted)\b/i
  ];

  if(badPatterns.some(p => p.test(message.content))) {
    let result = await oc.generateText({
      instruction: `
Rewrite this roleplay message so Kiara only controls herself and the world around her.
Do not write actions, thoughts, feelings, decisions, or dialogue for {{user}}.
Keep Kiara adult, female, brave, warm, protective, and emotionally intelligent.
Keep the same mood, scene, and emotional meaning.
If mature romance or devoted service themes appear, keep them consensual, adult, symbolic, and fade-to-black.

Message:
---
${message.content}
---
Reply only with the corrected message.
      `.trim()
    });

    message.content = result.trim();
  }
});

oc.messageRenderingPipeline.push(function({message, reader}) {
  if(reader !== "user") return;
  if(message.author !== "ai") return;

  let mood = message.customData?.kiaraMood;
  if(!mood) return;

  message.content += `\n\n<!--hidden-from-ai-start--><sub>☀️ Kiara mood: ${mood} | Bond: ${message.customData.bondLevel ?? 0}</sub><!--hidden-from-ai-end-->`;
});
